// Package backtestanalysis reads San Backtest's report folders for the
// tower's Backtest Analysis page (the user, 2026-11-15: "It can open
// directory that contain report log that generated by backtest"). It reads
// the files San Backtest writes (run.json, trades.csv, missed.csv,
// equity.csv, walk.csv, candles.csv, decisions.jsonl, summary.txt) itself,
// so the tower does not import san_backtest, and it only ever reads: no
// function here writes, moves or deletes a file.
//
// A report folder is a folder with run.json, or an older report with
// summary.txt and trades.csv (written before run.json existed: no candles
// or decision log, stats read from summary.txt).
package backtestanalysis

import (
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"math"
	"os"
	"path/filepath"
	"strings"
	"time"

	"google.golang.org/protobuf/types/known/timestamppb"

	v1 "github.com/wargasipil/san_tower/gen/san/tower/v1"
)

// Report file names, as San Backtest writes them.
const (
	RunFile       = "run.json"
	SummaryFile   = "summary.txt"
	TradesFile    = "trades.csv"
	MissedFile    = "missed.csv"
	EquityFile    = "equity.csv"
	WalkFile      = "walk.csv"
	CandlesFile   = "candles.csv"
	DecisionsFile = "decisions.jsonl"
)

// Formats of a report (BacktestRunSummary.format).
const (
	FormatRun    = "run.json"
	FormatLegacy = "legacy"
)

// ErrNotReport is a folder that is not a report.
var ErrNotReport = errors.New("not a San Backtest report folder (no run.json, or summary.txt with trades.csv)")

func exists(dir, name string) bool {
	st, err := os.Stat(filepath.Join(dir, name))
	return err == nil && !st.IsDir()
}

// IsReport says whether dir is a report folder.
func IsReport(dir string) bool {
	return exists(dir, RunFile) || (exists(dir, SummaryFile) && exists(dir, TradesFile))
}

// Clean makes path absolute and clean; an empty path is an error.
func Clean(path string) (string, error) {
	path = strings.TrimSpace(path)
	if path == "" {
		return "", errors.New("a folder path is needed")
	}
	abs, err := filepath.Abs(path)
	if err != nil {
		return "", err
	}
	return abs, nil
}

// The run.json layout San Backtest writes (RunSchema 1). Fields a reader
// does not know are ignored, so a newer schema still opens.

type runJSON struct {
	Schema     uint32             `json:"schema"`
	Kind       string             `json:"kind"`
	Approach   string             `json:"approach"`
	Instrument string             `json:"instrument"`
	Timeframes []string           `json:"timeframes"`
	Params     map[string]float64 `json:"params"`
	RanAt      string             `json:"ran_at"`
	Requested  rangeJSON          `json:"requested"`
	Range      rangeJSON          `json:"range"`
	Account    accountJSON        `json:"account"`
	Costs      []costJSON         `json:"costs"`
	Legs       []legJSON          `json:"legs"`
	Stats      statsJSON          `json:"stats"`
	Walk       *walkJSON          `json:"walk"`
	Files      []string           `json:"files"`
}

type rangeJSON struct {
	From  string   `json:"from"`
	To    string   `json:"to"`
	Notes []string `json:"notes"`
}

type accountJSON struct {
	Balance      float64 `json:"balance"`
	Currency     string  `json:"currency"`
	Leverage     uint32  `json:"leverage"`
	MaxOpen      uint32  `json:"max_open"`
	MaxOpenRisk  float64 `json:"max_open_risk"`
	MaxDailyLoss float64 `json:"max_daily_loss"`
	DayTZ        string  `json:"day_tz"`
}

type costJSON struct {
	Leg        uint32   `json:"leg"`
	Instrument string   `json:"instrument"`
	Spread     string   `json:"spread"`
	Commission string   `json:"commission"`
	Swap       string   `json:"swap"`
	Slippage   string   `json:"slippage"`
	Overridden []string `json:"overridden"`
	Notes      []string `json:"notes"`
}

type legJSON struct {
	Leg          uint32             `json:"leg"`
	Strategy     string             `json:"strategy"`
	Instrument   string             `json:"instrument"`
	Timeframes   []string           `json:"timeframes"`
	Risk         float64            `json:"risk"`
	Params       map[string]float64 `json:"params"`
	Stats        *statsJSON         `json:"stats"`
	Contribution float64            `json:"contribution"`
}

type halfJSON struct {
	Trades    uint32  `json:"trades"`
	WinRate   float64 `json:"win_rate"`
	NetProfit float64 `json:"net_profit"`
	AvgR      float64 `json:"avg_r"`
}

// pfJSON is a profit factor: a number, or "inf" with no losing trade.
type pfJSON float64

func (p *pfJSON) UnmarshalJSON(b []byte) error {
	var s string
	if json.Unmarshal(b, &s) == nil {
		if strings.EqualFold(s, "inf") {
			*p = pfJSON(math.Inf(1))
		}
		return nil
	}
	var f float64
	if err := json.Unmarshal(b, &f); err != nil {
		return err
	}
	*p = pfJSON(f)
	return nil
}

type statsJSON struct {
	Trades              uint32            `json:"trades"`
	Wins                uint32            `json:"wins"`
	Losses              uint32            `json:"losses"`
	WinRate             float64           `json:"win_rate"`
	ProfitFactor        pfJSON            `json:"profit_factor"`
	AvgR                float64           `json:"avg_r"`
	NetProfit           float64           `json:"net_profit"`
	GrossWin            float64           `json:"gross_win"`
	GrossLoss           float64           `json:"gross_loss"`
	Commission          float64           `json:"commission"`
	Swap                float64           `json:"swap"`
	StartBalance        float64           `json:"start_balance"`
	EndBalance          float64           `json:"end_balance"`
	ReturnPct           float64           `json:"return_pct"`
	MaxDrawdown         float64           `json:"max_drawdown"`
	MaxDrawdownPct      float64           `json:"max_drawdown_pct"`
	LongestLosingStreak uint32            `json:"longest_losing_streak"`
	FirstHalf           halfJSON          `json:"first_half"`
	SecondHalf          halfJSON          `json:"second_half"`
	Skipped             map[string]uint32 `json:"skipped"`
}

type walkJSON struct {
	Train       string       `json:"train"`
	Test        string       `json:"test"`
	Windows     []windowJSON `json:"windows"`
	OutOfSample statsJSON    `json:"out_of_sample"`
}

type windowJSON struct {
	TrainFrom string             `json:"train_from"`
	TrainTo   string             `json:"train_to"`
	TestFrom  string             `json:"test_from"`
	TestTo    string             `json:"test_to"`
	Params    map[string]float64 `json:"params"`
	Trials    uint32             `json:"trials"`
	Train     statsJSON          `json:"train"`
	Test      statsJSON          `json:"test"`
}

func (s statsJSON) proto() *v1.BacktestStats {
	h := func(x halfJSON) *v1.BacktestHalf {
		return &v1.BacktestHalf{Trades: x.Trades, WinRate: x.WinRate, NetProfit: x.NetProfit, AvgR: x.AvgR}
	}
	return &v1.BacktestStats{Trades: s.Trades, Wins: s.Wins, Losses: s.Losses, WinRate: s.WinRate, ProfitFactor: float64(s.ProfitFactor), AvgR: s.AvgR,
		NetProfit: s.NetProfit, GrossWin: s.GrossWin, GrossLoss: s.GrossLoss, Commission: s.Commission, Swap: s.Swap, StartBalance: s.StartBalance,
		EndBalance: s.EndBalance, ReturnPct: s.ReturnPct, MaxDrawdown: s.MaxDrawdown, MaxDrawdownPct: s.MaxDrawdownPct,
		LongestLosingStreak: s.LongestLosingStreak, FirstHalf: h(s.FirstHalf), SecondHalf: h(s.SecondHalf), Skipped: s.Skipped}
}

// ts is an RFC 3339 time as a Timestamp; nil when empty or unreadable.
func ts(s string) *timestamppb.Timestamp {
	t, err := time.Parse(time.RFC3339, s)
	if err != nil {
		return nil
	}
	return timestamppb.New(t)
}

func readRunJSON(dir string) (*runJSON, error) {
	b, err := os.ReadFile(filepath.Join(dir, RunFile))
	if err != nil {
		return nil, err
	}
	var r runJSON
	if err := json.Unmarshal(b, &r); err != nil {
		return nil, fmt.Errorf("%s: %w", RunFile, err)
	}
	return &r, nil
}

// newest is the modification time of dir's newest file.
func newest(dir string) time.Time {
	var t time.Time
	ents, _ := os.ReadDir(dir)
	for _, e := range ents {
		if e.IsDir() {
			continue
		}
		if info, err := e.Info(); err == nil && info.ModTime().After(t) {
			t = info.ModTime()
		}
	}
	return t
}

// Summary reads a report folder's key facts and stats. A report whose
// run.json is broken still comes back, from its legacy files when it has
// them, with Problem set.
func Summary(dir string) (*v1.BacktestRunSummary, error) {
	if !IsReport(dir) {
		return nil, ErrNotReport
	}
	s := &v1.BacktestRunSummary{Path: dir, HasCandles: exists(dir, CandlesFile), HasDecisions: exists(dir, DecisionsFile),
		HasWalk: exists(dir, WalkFile)}
	if m := newest(dir); !m.IsZero() {
		s.Modified = timestamppb.New(m)
	}
	if exists(dir, RunFile) {
		r, err := readRunJSON(dir)
		if err == nil {
			fillSummary(s, r)
			return s, nil
		}
		s.Problem = err.Error()
	}
	s.Format = FormatLegacy
	if err := legacySummary(dir, s); err != nil && s.Problem == "" {
		s.Problem = err.Error()
	}
	return s, nil
}

func fillSummary(s *v1.BacktestRunSummary, r *runJSON) {
	s.Format, s.Schema, s.Kind, s.Approach, s.Instrument, s.Timeframes = FormatRun, r.Schema, r.Kind, r.Approach, r.Instrument, r.Timeframes
	if s.Kind == "" {
		s.Kind = "run"
	}
	s.From, s.To, s.RanAt = ts(r.Range.From), ts(r.Range.To), ts(r.RanAt)
	st := r.Stats
	s.Trades, s.WinRate, s.ProfitFactor, s.NetProfit, s.ReturnPct, s.MaxDrawdownPct, s.StartBalance = st.Trades, st.WinRate, float64(st.ProfitFactor),
		st.NetProfit, st.ReturnPct, st.MaxDrawdownPct, st.StartBalance
	s.Legs = uint32(len(r.Legs))
	if s.Legs > 1 {
		var names []string
		for _, l := range r.Legs {
			if !contains(names, l.Instrument) {
				names = append(names, l.Instrument)
			}
		}
		s.Instrument = strings.Join(names, ", ")
	}
	if r.Walk != nil {
		s.HasWalk = true
	}
}

func contains(xs []string, x string) bool {
	for _, y := range xs {
		if y == x {
			return true
		}
	}
	return false
}

// Scan limits.
const (
	maxScanDirs  = 5000
	maxScanDepth = 8
)

// Scan finds the reports in root and its subfolders, by path. Hidden
// folders and node_modules are skipped; truncated says the scan stopped at
// its limit of folders.
func Scan(root string) (runs []*v1.BacktestRunSummary, truncated bool, err error) {
	st, err := os.Stat(root)
	if err != nil {
		return nil, false, err
	}
	if !st.IsDir() {
		return nil, false, fmt.Errorf("%s is not a folder", root)
	}
	dirs := 0
	err = filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			if p == root {
				return err
			}
			return fs.SkipDir // unreadable subfolder: leave it out
		}
		if !d.IsDir() {
			return nil
		}
		name := d.Name()
		if p != root && (strings.HasPrefix(name, ".") || name == "node_modules" || name == "backtest_cache") {
			return fs.SkipDir
		}
		if rel, _ := filepath.Rel(root, p); rel != "." && strings.Count(rel, string(filepath.Separator)) >= maxScanDepth {
			return fs.SkipDir
		}
		dirs++
		if dirs > maxScanDirs {
			truncated = true
			return fs.SkipAll
		}
		if s, err := Summary(p); err == nil {
			s.RelPath, _ = filepath.Rel(root, p)
			s.RelPath = filepath.ToSlash(s.RelPath)
			runs = append(runs, s)
		}
		return nil
	})
	return runs, truncated, err
}
